int main()
{
    int tc;
    cin >> tc;
    while(tc--)
    {
        string s;
        cin >> s;
        int n = s.length();
        set<char> c;
        bool ok = true;
        int k;
        for(k=0;k<n;k++)
        {
            if(c.find(s[k])==c.end())
                c.insert(s[k]);
            else
                break;
        }
        for(int i=k;i<n;i++)
        {
            if(s[i]!=s[i-k])
                ok = false;
        }
        if(ok)
            cout << "YES\n";
        else
            cout << "NO\n";
    }
}

#include <bits/stdc++.h>
using namespace std;

const int N = 40004, M = 502;
const long long MOD = 1000000007;
long long dp[N][M];

int reverse(int n)
{
    int r=0;
    while(n>0)
    {
        r=r*10+n%10;
        n/=10;
    }
    return r;
}

bool palindrome(int n)
{
    return (reverse(n)==n); 
}

int main()
{
    vector<int> palin;
    palin.push_back(0);
    for(int i=1;i<2*N;i++)
    {
        if(palindrome(i))
            palin.push_back(i);
    }
    for(int j=1;j<M;j++)
        dp[0][j]=1;
    for(int i=1;i<N;i++)
    {
        dp[i][0]=0;
        for(int j=1;j<M;j++)
        {
            if(palin[j]<=i)
                dp[i][j]=(dp[i][j-1]+dp[i-palin[j]][j])%MOD;
            else
                dp[i][j]=dp[i][j-1];
        }
    }
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int tc;
    cin >> tc;
    while(tc--)
    {
        int n;
        cin >> n;
        cout << dp[n][M-1] << '\n';
    }
}

#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000007;

long long gcd(long long a,long long b)
{
    if(b==0)
        return a;
    else
        return gcd(b,a%b);
}

long long lcm(long long a,long long b)
{
    long long g = gcd(a,b);
    return (a*b)/g;
}

int main()
{
    int tc;
    cin >> tc;
    while(tc--)
    {
        long long b,c,q,r,y,z;
        cin >> b >> q >> y;
        cin >> c >> r >> z;
        long long e = b+q*(y-1);
        long long f = c+r*(z-1);
        if(c<b || c>e || f<b || f>e || r%q!=0 || (c-b)%q!=0)
            cout << 0 << '\n';
        else if(c-r<b || f+r>e)
            cout << -1 << '\n';
        else
        {
            long long ans = 0;
            for(long long p=1;p*p<=r;p++)
            {
                if(r%p==0)
                {
                    if(lcm(p,q)==r)
                    {
                        long long a = ((r/p)*(r/p))%MOD;
                        ans = (ans+a)%MOD;
                    }
                    if(p*p!=r && lcm(r/p,q)==r)
                    {
                        long long a = (p*p)%MOD;
                        ans = (ans+a)%MOD;
                    }
                }
            }
            cout << ans << '\n';
        }
    }
}

#include <bits/stdc++.h>
using namespace std;

const int N = 1048576;
long long b[N];
char ans[N];

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n,k;
    cin >> n >> k;
    for(int i=0;i<n;i++)
    {
        cin >> b[i];
    }
    for(int i=0;i<1048576;i++)
        ans[i]='0';
    for(int l=0;l<n;l++)
    {
        long long p=1;
        for(int r=l;r<n;r++)
        {
            if(r==l)
                p*=b[r];
            else
            {
                if(b[r]>=20)
                    break;
                else
                    p*=(1ll<<b[r]);
            }
            if(p>=1048576)
                break;
            int m = n-r+l-3;
            int q = k-2;
            if(l==0)
            {
                m++;
                q++;
            }
            if(r==n-1)
            {
                m++;
                q++;
            }
            if(m>=q && (m==0 || (q>0 && ((m-1)|(q-1))==(m-1))))
                ans[p]='1'+'0'-ans[p];
        }
    }
    bool start=false;
    for(int i=1048575;i>=0;i--)
    {
        if(ans[i]=='0' && start)
            cout << 0;
        else if(ans[i]=='1')
        {
            cout << 1;
            start=true;
        }
    }
    if(!start)
        cout << 0;
    cout << '\n';
}

#include <bits/stdc++.h>
using namespace std;

const int N = 32;

int maxpower2(int n)
{
    int p=1;
    while(n%2==0)
    {
        p*=2;
        n/=2;
    }
    return p;
}

int main()
{
    int n,k;
    cin >> n >> k;
    int h[N][N-1];
    for(int i=0;i<N;i++)
    {
        for(int j=1;j<=N-1;j++)
        {
            h[i][j-1]=maxpower2(j)*maxpower2(j);
        }
    }
    for(int i=0;i<n;i++)
    {
        for(int j=0;j<n-1;j++)
        {
            cout << h[i][j] << " ";
        }
        cout << endl;
    }
    int v[N-1][N];
    for(int i=1;i<=N-1;i++)
    {
        for(int j=0;j<N;j++)
        {
            v[i-1][j]=2*maxpower2(i)*maxpower2(i);
        }
    }
    for(int i=0;i<n-1;i++)
    {
        for(int j=0;j<n;j++)
        {
            cout << v[i][j] << " ";
        }
        cout << endl;
    }
    int b[n][n];
    b[0][0]=0;
    for(int j=1;j<n;j++)
    {
        b[0][j]=b[0][j-1]^h[0][j-1];
    }
    for(int i=1;i<n;i++)
    {
        for(int j=0;j<n;j++)
        {
            b[i][j]=b[i-1][j]^v[i-1][j];
        }
    }
    map<int,pair<int,int> > m;
    for(int i=0;i<n;i++)
    {
        for(int j=0;j<n;j++)
        {
            m[b[i][j]]={i,j};
        }
    }
    int y=0;
    while(k--)
    {
        int x;
        cin >> x;
        pair<int,int> ans = m[x^y];
        cout << ans.first+1 << " " << ans.second+1 << endl;
        y^=x;
    }
}
